package com.payesh.app.data.local

import android.content.Context
import androidx.room.Database
import androidx.room.Room
import androidx.room.RoomDatabase
import androidx.sqlite.db.SupportSQLiteDatabase

@Database(entities = [ClaimEntity::class], version = 1, exportSchema = false)
abstract class AppDatabase : RoomDatabase() {
    abstract fun lawDao(): LawDao

    companion object {
        @Volatile private var INSTANCE: AppDatabase? = null

        fun getInstance(context: Context): AppDatabase = INSTANCE ?: synchronized(this) {
            INSTANCE ?: Room.databaseBuilder(
                context.applicationContext, AppDatabase::class.java, "payesh.db"
            ).addCallback(object : Callback() {
                override fun onCreate(db: SupportSQLiteDatabase) {
                    super.onCreate(db)
                    seed(db)
                }
            }).build().also { INSTANCE = it }
        }

        private fun seed(db: SupportSQLiteDatabase) {
            val data = listOf(
                arrayOf("الزام به تنظیم سند رسمی و تسلیم مبیع", "حقوقی", "دادگاه حقوقی محل وقوع ملک", "پس از انعقاد بیع، فروشنده مکلف به انتقال رسمی است؛ امکان مطالبه خسارات دادرسی نیز بررسی شود.", "مواد ۲۲۰، ۲۲۱ و ۱۳۰۱ قانون مدنی؛ قانون الزام به ثبت رسمی معاملات اموال غیرمنقول (۱۴۰۳)", "حسب مورد؛ مهلت‌ها و مقررات انتقالی قانون ۱۴۰۳ بررسی شود", "طبق تعرفه قانونی وکالت و هزینه‌های دادرسی"),
                arrayOf("کلاهبرداری اینترنتی و برداشت غیرمجاز", "کیفری", "دادسرای جرایم رایانه‌ای / پلیس فتا", "برداشت یا تحصیل مال از طریق سامانه‌های رایانه‌ای می‌تواند حسب اوضاع پرونده مشمول عناوین کیفری باشد.", "ماده ۱۳ قانون جرایم رایانه‌ای (مصوب ۱۳۸۸، با اصلاحات بعدی)؛ ماده ۱ قانون تشدید مجازات مرتکبین ارتشاء و اختلاس و کلاهبرداری حسب انطباق", "مهلت شکایت و مرور زمان با عنوان اتهامی و تاریخ وقوع سنجیده شود", "هزینه‌های قانونی و تعرفه وکالت"),
                arrayOf("مطالبه حقوق و مزایای معوقه کارگر", "کار", "اداره تعاون، کار و رفاه اجتماعی؛ هیأت تشخیص و حل اختلاف", "مطالبه حقوق، مزایا، عیدی، سنوات و حق بیمه بر پایه قرارداد، سوابق و مقررات کار بررسی می‌شود.", "مواد ۲۴، ۳۷ و ۱۴۸ قانون کار و مصوبات مرتبط", "بدون فرض مهلت واحد؛ وضعیت رابطه کار و مقررات مربوط بررسی شود", "رسیدگی مراجع کار تابع مقررات و هزینه‌های قانونی مربوط"),
                arrayOf("اعتراض به برگ تشخیص مالیات", "مالیاتی", "سازمان امور مالیاتی و هیأت حل اختلاف مالیاتی", "مودی می‌تواند در مهلت قانونی پس از ابلاغ، اعتراض مستدل و مستند خود را ارائه کند.", "مواد ۲۳۸، ۲۴۴ و ۲۵۱ مکرر قانون مالیات‌های مستقیم", "مهلت اعتراض اولیه اصولاً ۳۰ روز از ابلاغ برگ تشخیص؛ حسب مورد قانون جاری بررسی شود", "تعرفه وکالت و هزینه‌های قانونی"),
                arrayOf("اعتراض به رأی کمیسیون ماده ۱۰۰ شهرداری", "شهرداری", "دیوان عدالت اداری؛ حسب مرحله و موضوع", "اعتراض به تصمیم یا رأی قطعی مرجع اداری باید با رعایت صلاحیت، مهلت و تشریفات دیوان طرح شود.", "ماده ۱۰ قانون تشکیلات و آیین دادرسی دیوان عدالت اداری؛ ماده ۱۰۰ قانون شهرداری", "مهلت تابع قانون دیوان و نوع رأی/ابلاغ است؛ متن جاری کنترل شود", "تعرفه وکالت و هزینه‌های قانونی"),
                arrayOf("اعتراض به تصمیمات اداره ثبت", "ثبتی", "هیأت نظارت / شورای عالی ثبت یا دادگاه صالح حسب موضوع", "نوع اعتراض ثبتی، مرحله عملیات و ماهیت اختلاف تعیین‌کننده مرجع رسیدگی است.", "قانون ثبت اسناد و املاک و مقررات مرتبط، حسب موضوع", "مهلت بسته به نوع اعتراض و ابلاغ متفاوت است", "تعرفه وکالت و هزینه‌های قانونی"),
                arrayOf("مطالبه وجه چک صیادی", "تجاری", "دادگاه حقوقی یا اجرای ثبت/اجرای قضایی حسب مسیر قانونی", "دارنده چک می‌تواند با گواهی عدم پرداخت، حسب شرایط قانونی از مسیر حقوقی یا صدور اجراییه اقدام کند.", "قانون صدور چک، از جمله ماده ۲۳ و اصلاحات بعدی", "مهلت‌ها و شرایط به تاریخ چک، گواهی عدم پرداخت و مسیر انتخابی بستگی دارد", "هزینه دادرسی/اجرایی و تعرفه وکالت"),
                arrayOf("ثبت رسمی معاملات اموال غیرمنقول (قانون ۱۴۰۳)", "حقوقی", "دفاتر اسناد رسمی، سامانه‌های قانونی و محاکم حسب موضوع", "قانون الزام به ثبت رسمی معاملات اموال غیرمنقول مصوب ۱۴۰۳، آثار و ضمانت‌اجراهایی برای ثبت معاملات مقرر کرده است. تطبیق دقیق مواد انتقالی و زمان اجرا ضروری است.", "قانون الزام به ثبت رسمی معاملات اموال غیرمنقول مصوب ۱۴۰۳، به‌ویژه مواد ۱ و ۱۰", "مهلت‌ها به راه‌اندازی سامانه‌ها، مقررات اجرایی و وضعیت ملک بستگی دارد", "تعرفه‌های قانونی مربوط به ثبت و وکالت")
            )
            data.forEach { row ->
                db.execSQL("INSERT INTO claims(title,forum,authority,description,articles,deadline,feeRate) VALUES(?,?,?,?,?,?,?)", row)
            }
        }
    }
}
